// One record with two names: the alias must stay the same object, so the
// increment through `value` is what the read through `alias` observes.
export function openRecord() {
  const value = { next: undefined, count: 0 };
  const alias = value;
  alias.next = { value: 42 };
  value.count++;
  return [alias.next.value, alias.count];
}
